const $=id=>document.getElementById(id),DB_NAME='chords-db',DB_VERSION=1;
const state={songs:[],view:'artists',artist:null,song:null,transpose:0,scrolling:false,scrollFrame:null,lastTime:0};
const settings=JSON.parse(localStorage.getItem('chords-settings')||'{}');
let favorites=new Set(JSON.parse(localStorage.getItem('chords-favorites')||'[]'));
let localEdits=JSON.parse(localStorage.getItem('chords-local-edits')||'{}');
const NOTES_SHARP=['C','C#','D','D#','E','F','F#','G','G#','A','A#','B'];
const NOTE_INDEX={C:0,'C#':1,Db:1,D:2,'D#':3,Eb:3,E:4,F:5,'F#':6,Gb:6,G:7,'G#':8,Ab:8,A:9,'A#':10,Bb:10,H:11,B:11};
const chordToken=/^([A-H])([#b]?)(.*)$/,chordOnly=/^[\s|:./()\[\]{},x\d-]*(?:[A-H](?:#|b)?(?:m|maj|min|sus|dim|aug|add)?\d*(?:\/[A-H](?:#|b)?)?[\s|:./()\[\]{},x\d-]*)+$/i;
let wakeLock=null;

function openDb(){return new Promise((resolve,reject)=>{const request=indexedDB.open(DB_NAME,DB_VERSION);request.onupgradeneeded=()=>{const db=request.result;if(!db.objectStoreNames.contains('songs'))db.createObjectStore('songs',{keyPath:'id'});if(!db.objectStoreNames.contains('meta'))db.createObjectStore('meta',{keyPath:'key'})};request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)})}
async function dbGet(store,key){const db=await openDb();return new Promise((resolve,reject)=>{const r=db.transaction(store).objectStore(store).get(key);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function dbPut(store,value){const db=await openDb();return new Promise((resolve,reject)=>{const tx=db.transaction(store,'readwrite');tx.objectStore(store).put(value);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
async function dbDelete(store,key){const db=await openDb();return new Promise((resolve,reject)=>{const tx=db.transaction(store,'readwrite');tx.objectStore(store).delete(key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
function persist(){localStorage.setItem('chords-settings',JSON.stringify(settings))}
function persistLocalEdits(){localStorage.setItem('chords-local-edits',JSON.stringify(localEdits))}
function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.remove('show'),2400)}
function normalize(value){return value.toLowerCase().replace(/ё/g,'е')}
function escapeHtml(s){return s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function plural(n,a,b,c){const n10=n%10,n100=n%100;return n10===1&&n100!==11?a:n10>=2&&n10<=4&&(n100<12||n100>14)?b:c}
function groups(){const map=new Map();for(const song of state.songs){if(!map.has(song.artist))map.set(song.artist,[]);map.get(song.artist).push(song)}return[...map].sort((a,b)=>a[0].localeCompare(b[0],'ru'))}
function setHeader(title,back=false){$('pageTitle').textContent=title;$('backBtn').classList.toggle('hidden',!back)}
function row(icon,title,meta,onClick){const button=document.createElement('button');button.className='artist-row';button.innerHTML=`<span class="row-icon">${icon}</span><span class="row-copy"><span class="row-title">${escapeHtml(title)}</span><span class="row-meta">${escapeHtml(meta)}</span></span><span class="chevron">›</span>`;button.onclick=onClick;return button}
function showLibrary(){stopScroll();state.song=null;$('songView').classList.add('hidden');$('libraryView').classList.remove('hidden');$('updateBtn').classList.remove('hidden');window.scrollTo(0,0);renderLibrary()}
function renderLibrary(){const query=normalize($('searchInput').value.trim()),list=$('libraryList');list.innerHTML='';if(query){state.view='search';setHeader('Поиск');const matches=state.songs.filter(s=>normalize(`${s.artist} ${s.title}`).includes(query));$('summaryText').textContent=`Найдено: ${matches.length}`;for(const song of matches)list.append(row('♪',song.title,song.artist,()=>openSong(song)));if(!matches.length)list.innerHTML='<div class="empty">Ничего не найдено</div>';return}if(state.artist){state.view='songs';setHeader(state.artist,true);const songs=state.songs.filter(s=>s.artist===state.artist);$('summaryText').textContent=`${songs.length} ${plural(songs.length,'песня','песни','песен')}`;for(const song of songs)list.append(row(favorites.has(song.id)?'★':'♪',song.title,favorites.has(song.id)?'В избранном':'Открыть аккорды',()=>openSong(song)))}else{state.view='artists';setHeader('Мои аккорды');const all=groups();$('summaryText').textContent=`${state.songs.length} ${plural(state.songs.length,'песня','песни','песен')} · ${all.length} исполнителей`;for(const[artist,songs]of all)list.append(row(artist[0].toUpperCase(),artist,`${songs.length} ${plural(songs.length,'песня','песни','песен')}`,()=>{state.artist=artist;renderLibrary();window.scrollTo(0,0)}))}}
function isTabLine(line){return /^\s*[eEBGDA]\|/.test(line)}
function isChordLine(line){const trimmed=line.trim();return!isTabLine(line)&&trimmed.length>0&&trimmed.length<100&&chordOnly.test(trimmed)}
function alignedSongLines(text){const lines=text.split('\n'),first=lines.findIndex(line=>line.trim());if(first>=0&&isChordLine(lines[first])&&!/^\s/.test(lines[first])){const next=lines.slice(first+1).find(line=>line.trim()),indent=next?.match(/^\s+/)?.[0];if(indent)lines[first]=indent+lines[first]}return lines}
function transposeChord(token,steps){const match=token.match(chordToken);if(!match)return token;const key=match[1].toUpperCase()+match[2],index=NOTE_INDEX[key];if(index===undefined)return token;let suffix=match[3];suffix=suffix.replace(/\/([A-H])([#b]?)/g,(_,n,a)=>'/'+NOTES_SHARP[(NOTE_INDEX[n.toUpperCase()+a]+steps+120)%12]);return NOTES_SHARP[(index+steps+120)%12]+suffix}
function renderSongText(){const html=alignedSongLines(state.song.text).map(line=>{if(isTabLine(line))return`<div class="song-line tab-line">${escapeHtml(line)||' '}</div>`;if(isChordLine(line)){const changed=line.replace(/[A-H](?:#|b)?[^\s|:,()\[\]]*/g,token=>transposeChord(token,state.transpose));return`<div class="song-line chord-line">${escapeHtml(changed)||' '}</div>`}return`<div class="song-line">${escapeHtml(line)||' '}</div>`}).join('');$('songContent').innerHTML=html;$('transposeValue').textContent=state.transpose>0?`+${state.transpose}`:state.transpose}
async function openSong(song){let stored=await dbGet('songs',song.id);if(!stored?.text&&navigator.onLine){await syncLibrary(false);stored=await dbGet('songs',song.id)}const fallback=localEdits[song.id];if(!stored?.text&&!fallback?.text){toast('Песня ещё не загружена на устройство');return}state.song={...song,text:fallback?.text||stored.text,localEdit:!!fallback||!!stored.localEdit};state.transpose=0;$('libraryView').classList.add('hidden');$('songView').classList.remove('hidden');$('updateBtn').classList.add('hidden');$('songArtist').textContent=song.artist;$('songTitle').textContent=song.title;setHeader(song.artist,true);updateFavorite();updateLocalEditStatus();renderSongText();window.scrollTo(0,0)}
function updateLocalEditStatus(){$('localEditStatus').classList.toggle('hidden',!state.song?.localEdit)}
function openEditor(){$('songEditor').value=state.song.text;$('editorTitle').textContent=state.song.title;$('editorDialog').classList.remove('hidden');document.body.style.overflow='hidden';setTimeout(()=>$('songEditor').focus(),50)}
function closeEditor(){$('editorDialog').classList.add('hidden');document.body.style.overflow=''}
async function saveLocalEdit(){const text=$('songEditor').value.replace(/\r\n?/g,'\n').trim();if(!text){toast('Текст песни не может быть пустым');return}try{const record=await dbGet('songs',state.song.id),originalText=record?.originalText||record?.text||state.song.text;localEdits[state.song.id]={text,updatedAt:Date.now()};persistLocalEdits();await dbPut('songs',{...record,id:state.song.id,version:state.song.version,originalText,text,localEdit:true});const saved=await dbGet('songs',state.song.id);if(saved?.text!==text)throw new Error('Проверка сохранения не пройдена');state.song.text=text;state.song.localEdit=true;renderSongText();updateLocalEditStatus();closeEditor();toast('Сохранено на этом устройстве')}catch{toast('Не удалось сохранить. Проверьте доступ к хранилищу')}}
async function restoreOriginal(){try{const record=await dbGet('songs',state.song.id);if(!record?.originalText){toast('Исходный текст не найден');return}delete localEdits[state.song.id];persistLocalEdits();await dbPut('songs',{...record,text:record.originalText,localEdit:false});state.song.text=record.originalText;state.song.localEdit=false;$('songEditor').value=record.originalText;renderSongText();updateLocalEditStatus();closeEditor();toast('Исходный текст восстановлен')}catch{toast('Не удалось восстановить исходный текст')}}
function updateFavorite(){$('favoriteBtn').textContent=favorites.has(state.song.id)?'★':'☆';$('favoriteBtn').setAttribute('aria-label',favorites.has(state.song.id)?'Убрать из избранного':'Добавить в избранное')}
function goBack(){if(state.song){showLibrary();return}if(state.artist){state.artist=null;renderLibrary();window.scrollTo(0,0)}}
function setTranspose(delta){state.transpose=Math.max(-11,Math.min(11,state.transpose+delta));renderSongText()}
function setFont(delta){const size=Math.max(14,Math.min(30,(settings.fontSize||18)+delta));settings.fontSize=size;document.documentElement.style.setProperty('--song-size',size+'px');persist()}
function stopScroll(){state.scrolling=false;cancelAnimationFrame(state.scrollFrame);$('scrollIcon').textContent='▶';state.lastTime=0}
function tick(time){if(!state.scrolling)return;if(state.lastTime){const speed=Number($('speedRange').value);window.scrollBy(0,(time-state.lastTime)*speed/55)}state.lastTime=time;if(window.innerHeight+window.scrollY>=document.documentElement.scrollHeight-2){stopScroll();return}state.scrollFrame=requestAnimationFrame(tick)}
function toggleScroll(){if(state.scrolling)stopScroll();else{state.scrolling=true;$('scrollIcon').textContent='Ⅱ';state.lastTime=0;state.scrollFrame=requestAnimationFrame(tick)}}
function applySettings(){const theme=settings.theme||(matchMedia('(prefers-color-scheme:dark)').matches?'dark':'light');document.documentElement.dataset.theme=theme;document.documentElement.style.setProperty('--song-size',(settings.fontSize||18)+'px');$('speedRange').value=settings.speed||3;$('speedValue').textContent=$('speedRange').value;$('themeIcon').textContent=theme==='dark'?'☀':'☾';updateWakeButton()}
function updateWakeButton(){const active=!!settings.keepAwake;$('wakeBtn').classList.toggle('active',active);$('wakeIcon').textContent=active?'●':'◉';$('wakeBtn').title=active?'Разрешить выключение экрана':'Не выключать экран';$('wakeBtn').setAttribute('aria-label',$('wakeBtn').title)}
async function requestWakeLock(showMessage=true){if(!('wakeLock'in navigator)){settings.keepAwake=false;persist();updateWakeButton();if(showMessage)toast('Устройство не поддерживает запрет выключения экрана');return}try{wakeLock=await navigator.wakeLock.request('screen');settings.keepAwake=true;persist();updateWakeButton();wakeLock.addEventListener('release',()=>{wakeLock=null})}catch{settings.keepAwake=false;persist();updateWakeButton();if(showMessage)toast('Не удалось включить запрет выключения экрана')}}
async function toggleWakeLock(){if(settings.keepAwake){settings.keepAwake=false;persist();await wakeLock?.release();wakeLock=null;updateWakeButton();toast('Экран может выключаться')}else{await requestWakeLock(false);if(settings.keepAwake)toast('Экран не будет гаснуть')}}
async function fetchText(file){const response=await fetch(encodeURI(file),{cache:'no-store'});if(!response.ok)throw new Error(`HTTP ${response.status}`);return response.text()}
async function syncLibrary(showMessage=true){if(!navigator.onLine){if(showMessage)toast('Нет подключения к интернету');return false}if(showMessage)toast('Проверяю обновления…');$('offlineStatus').textContent='Синхронизация…';try{const response=await fetch(`catalog.json?v=${Date.now()}`,{cache:'no-store'});if(!response.ok)throw new Error();const catalog=await response.json(),oldCatalog=(await dbGet('meta','catalog'))?.value,changed=[];for(const song of catalog.songs){const stored=await dbGet('songs',song.id),old=oldCatalog?.songs?.find(item=>item.id===song.id);if(stored?.localEdit||localEdits[song.id]){if(!stored||stored.version!==song.version){const originalText=await fetchText(song.file);await dbPut('songs',{...stored,id:song.id,version:song.version,text:localEdits[song.id]?.text||stored?.text||originalText,originalText,localEdit:true})}continue}if(!old||old.version!==song.version||!stored?.text)changed.push(song)}let completed=0;for(const song of changed){const text=await fetchText(song.file);await dbPut('songs',{id:song.id,version:song.version,text,originalText:text,localEdit:false});completed++;$('offlineStatus').textContent=`Загрузка ${completed}/${changed.length}`}const newIds=new Set(catalog.songs.map(song=>song.id));for(const old of oldCatalog?.songs||[])if(!newIds.has(old.id))await dbDelete('songs',old.id);await dbPut('meta',{key:'catalog',value:catalog});state.songs=catalog.songs;renderLibrary();$('offlineStatus').textContent='Доступно офлайн';if(showMessage)toast(changed.length?`Обновлено песен: ${changed.length}`:'У вас последняя версия');return true}catch{$('offlineStatus').textContent=state.songs.length?'Доступно офлайн':'Ошибка загрузки';if(showMessage)toast('Не удалось загрузить обновления');return false}}
async function initialize(){applySettings();if(settings.keepAwake)requestWakeLock(false);const saved=(await dbGet('meta','catalog'))?.value;if(saved){state.songs=saved.songs;renderLibrary();$('offlineStatus').textContent='Доступно офлайн'}else{$('libraryList').innerHTML='<div class="empty">Загружаю песни на устройство…</div>';$('summaryText').textContent=''}if(navigator.onLine)await syncLibrary(false);else if(!saved){$('offlineStatus').textContent='Нужен интернет';$('libraryList').innerHTML='<div class="empty">Для первой загрузки библиотеки подключитесь к интернету</div>'}}
$('searchInput').addEventListener('input',renderLibrary);$('backBtn').onclick=goBack;$('transposeDown').onclick=()=>setTranspose(-1);$('transposeUp').onclick=()=>setTranspose(1);$('fontDown').onclick=()=>setFont(-1);$('fontUp').onclick=()=>setFont(1);$('scrollToggle').onclick=toggleScroll;$('favoriteBtn').onclick=()=>{favorites.has(state.song.id)?favorites.delete(state.song.id):favorites.add(state.song.id);localStorage.setItem('chords-favorites',JSON.stringify([...favorites]));updateFavorite()};$('speedRange').addEventListener('input',event=>{$('speedValue').textContent=event.target.value;settings.speed=event.target.value;persist()});$('themeBtn').onclick=()=>{settings.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';applySettings();persist()};$('wakeBtn').onclick=toggleWakeLock;$('updateBtn').onclick=()=>syncLibrary(true);$('editSongBtn').onclick=openEditor;$('editorClose').onclick=closeEditor;$('editorCancel').onclick=closeEditor;$('editorSave').onclick=saveLocalEdit;$('restoreSongBtn').onclick=restoreOriginal;$('editorDialog').addEventListener('click',event=>{if(event.target===$('editorDialog'))closeEditor()});document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!$('editorDialog').classList.contains('hidden'))closeEditor()});document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&settings.keepAwake&&!wakeLock)requestWakeLock(false)});
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js');initialize();
